#define BALLCOUNT 20
#define COPYCOUNT 20

float disk(vec2 uv, vec2 pos, float radius){
    return length(uv - pos) - radius;
}

float PingPongTime(float time, float deform){
    int t = int(floor(time));
    float res = (t % 2 == 0) ? fract(time) : 1.0 - fract(time);
    return pow(res, deform);
}

uint murmurHash3(uint h) {
	h ^= h >> 16;
	h *= uint(0x85ebca6b);
	h ^= h >> 13;
	h *= uint(0xc2b2ae3d);
	h ^= h >> 16;
	return h;
}

float random(uint state){
    return float(murmurHash3(state)) / 4294967295.0;
}

vec3 randomColor(uint state){
    float randHue = random(state);
    vec3 rgb = clamp( abs(mod(randHue*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
    return rgb;
}

float remap(float In, vec2 InMinMax, vec2 OutMinMax)
{
    return (OutMinMax.x + (In - InMinMax.x) * (OutMinMax.y - OutMinMax.x) / (InMinMax.y - InMinMax.x));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float ratio = iResolution.x / iResolution.y;
    uv.x *= ratio;

    float time = iTime;

    vec3 finalColor = vec3(0.0);

    float trailSize = 0.02;
    for(int j = 0; j < COPYCOUNT; j++){
        time += trailSize * (float(j) / float(COPYCOUNT));
        finalColor *= 0.8;

        for(int i = 0; i < BALLCOUNT; i++){
            float ballRadius = random(uint(i)) * 0.03 + 0.01;

            int Xperiod = int(floor(time * (random(uint(i)) + 0.5)));
            int Yperiod = int(floor(time * (random(uint(i + 5456)) + 0.5)));

            float XTime = PingPongTime(time * (random(uint(i)) + 0.5), 1.0);
            float YTime = PingPongTime(time * (random(uint(i + 5456)) + 0.5), random(uint(i + Yperiod + 6458)) * 1.75 + 0.25);

            float ballXPos = remap(XTime, vec2(0.0, 1.0), vec2(ballRadius, ratio - ballRadius));
            float ballYPos = remap(YTime, vec2(0.0, 1.0), vec2(ballRadius, 1.0 - ballRadius));

            vec3 ballColor = randomColor(uint(i * 20 + 5884));

            float sdf = disk(uv, vec2(ballXPos, ballYPos), ballRadius * pow(float(j) / float(COPYCOUNT-1), 2.0));
            finalColor = mix(ballColor, finalColor, smoothstep(-0.005, 0.0, sdf));
        }
    }

    // Output to screen
    fragColor = vec4(finalColor,1.0);
}
